import type {
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import {
  decodeCanonicalDecimal,
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeCanonicalDecimal,
  isId,
  isQuantity,
  isRecord,
  isRevision,
  isUnits,
} from "./validation";
import { error } from "./reservation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type LookupResult<T> =
  | { kind: "found"; value: T }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function decodeReadEnvelope(raw: unknown): LookupResult<unknown> {
  if (!isRecord(raw) || typeof raw.ok !== "boolean") return { kind: "unavailable" };
  if (raw.ok) {
    return Object.hasOwn(raw, "value") && raw.value !== null
      ? { kind: "found", value: raw.value }
      : { kind: "unavailable" };
  }
  if (!isRecord(raw.error) || typeof raw.error.reason !== "string") return { kind: "unavailable" };
  return raw.error.reason === "NO_SUCH_KEY" ? { kind: "missing" } : { kind: "unavailable" };
}

function stockFromRow(row: ProviderBStockRow, requestedSku: string): Stock | undefined {
  const totalUnits = decodeCanonicalDecimal(row.onHandText);
  const reservedUnits = decodeCanonicalDecimal(row.heldText);
  const revision = decodeCanonicalDecimal(row.revisionText);
  if (row.itemKey !== requestedSku || totalUnits === undefined ||
      reservedUnits === undefined || revision === undefined ||
      !isUnits(totalUnits) || !isUnits(reservedUnits) || reservedUnits > totalUnits ||
      !isRevision(revision)) return undefined;
  return { sku: row.itemKey, totalUnits, reservedUnits, revision };
}

function reservationFromRow(row: ProviderBReservationRow, requestedReservationId: string): Reservation | undefined {
  const quantity = decodeCanonicalDecimal(row.unitsText);
  if (row.bookingKey !== requestedReservationId || quantity === undefined ||
      !isQuantity(quantity)) return undefined;
  return {
    reservationId: row.bookingKey,
    sku: row.itemKey,
    quantity,
  };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<LookupResult<Stock>> {
  const lookup = decodeReadEnvelope(await storage.read({ collection: "inventory", key: sku }));
  if (lookup.kind !== "found") return lookup;
  const row = decodeProviderBStockRow(lookup.value);
  const stock = row ? stockFromRow(row, sku) : undefined;
  return stock ? { kind: "found", value: stock } : { kind: "unavailable" };
}

async function readReservation(
  storage: ProviderBStorage,
  reservationId: string,
): Promise<LookupResult<Reservation>> {
  const lookup = decodeReadEnvelope(await storage.read({ collection: "reservations", key: reservationId }));
  if (lookup.kind !== "found") return lookup;
  const row = decodeProviderBReservationRow(lookup.value);
  const reservation = row ? reservationFromRow(row, reservationId) : undefined;
  return reservation ? { kind: "found", value: reservation } : { kind: "unavailable" };
}

function availabilityResponse(stock: Stock): ServiceResponse {
  return {
    status: 200,
    body: {
      sku: stock.sku,
      totalUnits: stock.totalUnits,
      reservedUnits: stock.reservedUnits,
      availableUnits: stock.totalUnits - stock.reservedUnits,
    },
  };
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        if (command.op === "getAvailability") {
          const stock = await readStock(storage, command.sku);
          if (stock.kind === "missing") return error(404, "stock_not_found");
          if (stock.kind === "unavailable") return error(500, "storage_unavailable");
          return availabilityResponse(stock.value);
        }

        const existing = await readReservation(storage, command.reservationId);
        if (existing.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing.kind === "found"
            ? reservationResponse(200, existing.value)
            : error(404, "reservation_not_found");
        }
        if (existing.kind === "found") {
          return existing.value.sku === command.sku && existing.value.quantity === command.quantity
            ? reservationResponse(200, existing.value)
            : error(409, "reservation_conflict");
        }

        const stock = await readStock(storage, command.sku);
        if (stock.kind === "missing") return error(404, "stock_not_found");
        if (stock.kind === "unavailable") return error(500, "storage_unavailable");
        if (stock.value.totalUnits - stock.value.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }

        const nextRevision = stock.value.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const unitsText = encodeCanonicalDecimal(reservation.quantity);
        const outcome = await storage.commitBatch({
          expectedRevisionText: encodeCanonicalDecimal(stock.value.revision),
          stockRow: {
            itemKey: stock.value.sku,
            onHandText: encodeCanonicalDecimal(stock.value.totalUnits),
            heldText: encodeCanonicalDecimal(stock.value.reservedUnits + reservation.quantity),
            revisionText: encodeCanonicalDecimal(nextRevision),
          },
          reservationRow: {
            bookingKey: reservation.reservationId,
            itemKey: reservation.sku,
            unitsText,
          },
          outboxRows: [{
            key: "reservation.created:" + reservation.reservationId,
            category: "reservation",
            name: "created",
            payload: {
              bookingKey: reservation.reservationId,
              itemKey: reservation.sku,
              unitsText,
            },
          }],
        });
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

